    [6667]={name="Engineer's Cloak",quality=2,ilvl=27,sourceType="quest_reward",instructions="Reward from the quest 'Gerenzo Wrenchwhistle'. Pick it over the other reward choices.",zone="Stonetalon Mountains",questName="Gerenzo Wrenchwhistle",lore="I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones."},
