    [9534]={name="Engineer's Guild Headpiece",quality=3,ilvl=47,sourceType="quest_reward",instructions="Reward from the quest 'Divino-matic Rod'. Pick it over the other reward choices.",zone="Zul'Farrak",questName="Divino-matic Rod",lore="Sergeant Bly stole from me! He said he'd only borrow it, but he stole my cherished divino-matic rod!! Without that rod how will I know where to dig new water holes??"},
    [9536]={name="Fairywing Mantle",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'A Fine Mess'. Pick it over the other reward choices.",zone="Gnomeregan",questName="A Fine Mess",lore="Wha.. What happened? The last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs."},
    [9605]={name="Repairman's Cape",quality=2,ilvl=30,sourceType="quest_reward",instructions="Reward from the quest 'Data Rescue'.",zone="Gnomeregan",questName="Data Rescue",lore="When we fled Gnomeregan, we left so much data behind! Vitally important data! I need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan."},
    [9652]={name="Gryphon Rider's Leggings",quality=3,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Saving Sharpbeak'. Pick it over the other reward choices.",zone="The Hinterlands",questName="Saving Sharpbeak",lore="We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!"},
    [9678]={name="Tok'kar's Murloc Basher",quality=2,ilvl=43,sourceType="quest_reward",instructions="Reward from the quest 'Threat From the Sea'. Pick it over the other reward choices.",zone="Swamp of Sorrows",questName="Threat From the Sea",lore="Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you."},
