    [10637]={name="Brewer's Gloves",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Sample for Helbrim'. Pick it over the other reward choices.",zone="Undercity",questName="Sample for Helbrim",lore="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."},
    [10638]={name="Long Draping Cape",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Sample for Helbrim'. Pick it over the other reward choices.",zone="Undercity",questName="Sample for Helbrim",lore="A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."},
    [10659]={name="Shard of the Splithooves",quality=2,ilvl=57,sourceType="quest_reward",instructions="Reward from the quest 'Heroes of Old'.",zone="Blasted Lands",questName="Heroes of Old",lore="Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."},
    [10739]={name="Ring of Fortitude",quality=2,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Rise, Obsidion!'. Pick it over the other reward choices.",zone="Searing Gorge",questName="Rise, Obsidion!",lore="It... It... It was all a trap. Forgive... me. Kill the bastard... Kill him for us... for Thorius."},
    [10748]={name="Wanderlust Boots",quality=2,ilvl=41,sourceType="quest_reward",instructions="Reward from the quest 'Mazen's Behest'. Pick it over the other reward choices.",zone="Stormwind City",questName="Mazen's Behest",lore="Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep. But I had never been to the Blasted Lands before!"},
