    [10787]={name="Atal'ai Gloves",quality=3,ilvl=52,reqLevel=47,sourceType="boss_drop",instructions="Drops from Zolo.",zone="Sunken Temple",npc="Zolo"},
    [10821]={name="Sower's Cloak",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Mura Runetotem'. Pick it over the other reward choices.",zone="The Barrens",questName="Mura Runetotem",lore="My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."},
    [11469]={name="Bloodband Bracers",quality=2,ilvl=46,sourceType="quest_reward",instructions="Reward from the quest 'The Captain's Chest'.",zone="Stranglethorn Vale",questName="The Captain's Chest",lore="I used to sail a ship from here all the way to Ratchet, in Kalimdor. I was a successful captain with a sterling reputation. Until... Those cursed sea giants ruined me!"},
    [11766]={name="Flameweave Cuffs",quality=3,ilvl=57,reqLevel=52,sourceType="boss_drop",instructions="Drops from Lord Incendius.",zone="Blackrock Depths",npc="Lord Incendius"},
    [11811]={name="Smoking Heart of the Mountain",quality=3,ilvl=55,reqLevel=50,sourceType="profession",instructions="Crafted with Enchanting (requires skill 1).",profession="Enchanting"},
    [11855]={name="Tork Wrench",quality=2,ilvl=19,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange Manual'. Pick it over the other reward choices.",zone="The Barrens",questName="Samophlange Manual",lore="I think I can fix the samophlange, but I'm going to need the user's manual first."},
    [11864]={name="White Bone Spear",quality=2,ilvl=52,sourceType="quest_reward",instructions="Reward from the quest 'Bone-Bladed Weapons'. Pick it over the other reward choices.",zone="Orgrimmar",questName="Bone-Bladed Weapons",lore="In Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death."},
    [11866]={name="Nagmara's Whipping Belt",quality=3,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'The Love Potion'. Pick it over the other reward choices.",zone="Blackrock Depths",questName="The Love Potion",lore="Oh, the pains of love! My dear Private Rocknot is immune to my charms. I am spurned! It's maddening! You must help me! We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart."},
    [11869]={name="Sha'ni's Ring",quality=2,ilvl=53,sourceType="quest_reward",instructions="Reward from the quest 'Krom'Grul'.",zone="Burning Steppes",questName="Krom'Grul",lore="My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger."},
    [11874]={name="Clouddrift Mantle",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'Ancient Spirit'. Pick it over the other reward choices.",zone="Felwood",questName="Ancient Spirit",lore="Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos... The skull of Gul'dan ensured that none were spared here."},
    [11876]={name="Plainstalker Tunic",quality=2,ilvl=56,sourceType="quest_reward",instructions="Reward from the quest 'The Bait for Lar'korwi'. Pick it over the other reward choices.",zone="Un'Goro Crater",questName="The Bait for Lar'korwi",lore="This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains."},
