    [21311]={name="Earth Warder's Vest",quality=2,ilvl=48,sourceType="quest_reward",instructions="Reward from the quest 'Timbermaw Ally'. Pick it over the other reward choices.",zone="Felwood",questName="Timbermaw Ally",lore="The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe."},
    [21317]={name="Helm of the Pathfinder",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Deadwood of the North'. Pick it over the other reward choices.",zone="Timbermaw Hold",questName="Deadwood of the North",lore="There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."},
    [21357]={name="Genesis Vest",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Genesis Vest'.",zone="Ahn'Qiraj",questName="Genesis Vest",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21409]={name="Cloak of Unending Life",quality=4,ilvl=67,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Cloak of Unending Life'.",zone="Ahn'Qiraj",questName="Cloak of Unending Life",lore="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."},
    [21507]={name="Amulet of the Shifting Sands",quality=4,ilvl=70,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Fall of Ossirian'. Pick it over the other reward choices.",zone="Ruins of Ahn'Qiraj",questName="The Fall of Ossirian",lore="A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory."},
